#!/usr/bin/env bash
set -euo pipefail
python3 - "$@" <<'PY'
import csv,hashlib,os,shutil,sys,tempfile
from pathlib import Path
source,manifest,dest=map(Path,sys.argv[1:4])
dry=False
with manifest.open() as f:rows=list(csv.DictReader(f,delimiter='\t'))
for r in rows:
    path=source/r['source']
    if not path.is_file() or hashlib.sha256(path.read_bytes()).hexdigest()!=r['sha256']:sys.exit(2)
if dry:
    for r in sorted(rows,key=lambda r:r['target']):print(r['target']+'\t'+r['sha256'])
    sys.exit(0)
dest.parent.mkdir(parents=True,exist_ok=True)
stage=Path(tempfile.mkdtemp(prefix='release-stage-',dir=dest.parent))
try:
    for r in rows:
        target=stage/r['target'];target.parent.mkdir(parents=True,exist_ok=True);shutil.copyfile(source/r['source'],target)
    if dest.exists():shutil.rmtree(dest)
    os.replace(stage,dest)
finally:
    if stage.exists():shutil.rmtree(stage)
